import os
from openai import OpenAI

def invoke_platform_model(payload, config=None):
    config = config or {}
    client = OpenAI(
        api_key=config.get("api_key") or os.environ["OPENAI_API_KEY"],
        project=config.get("project") or os.environ.get("OPENAI_PROJECT"),
    )
    result = client.responses.create(
        model=config.get("model", "gpt-4.1-mini"),
        input=payload if isinstance(payload, (str, list)) else str(payload),
    ).output_text
    return result
